/**
 * An account restriction carried in the session. The session stays valid.
 */

public enum AccountRestriction: Equatable, Hashable {
    
    case ageVerification(region: String
    )
    case timedBan(expiresAt: Int64?, reason: String?
    )
    case trustVendorRejected
    case other(value: String
    )





}

#if compiler(>=6)
extension AccountRestriction: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAccountRestriction: FfiConverterRustBuffer {
    typealias SwiftType = AccountRestriction

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AccountRestriction {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ageVerification(region: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .timedBan(expiresAt: try FfiConverterOptionInt64.read(from: &buf), reason: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .trustVendorRejected
        
        case 4: return .other(value: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AccountRestriction, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .ageVerification(region):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(region, into: &buf)
            
        
        case let .timedBan(expiresAt,reason):
            writeInt(&buf, Int32(2))
            FfiConverterOptionInt64.write(expiresAt, into: &buf)
            FfiConverterOptionString.write(reason, into: &buf)
            
        
        case .trustVendorRejected:
            writeInt(&buf, Int32(3))
        
        
        case let .other(value):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(value, into: &buf)
            
        }
    }
}


